public static void handle(PacketPlayMovingSound message, IPayloadContext ctx) {
        if (message.source() != null) message.source().handle(message.sound());
    }

public void handle(MovingSounds.Sound sound) {
            entityOrPos
                    .ifLeft(id -> {
                        Entity e = ClientUtils.getClientLevel().getEntity(id);
                        if (e != null) {
                            MovingSounds.playMovingSound(sound, e);
                        }
                    })
                    .ifRight(pos -> MovingSounds.playMovingSound(sound, pos));
        }

private static AbstractTickableSoundInstance createMovingSound(Sound s, Object focus, Object... extraData) {
        ClientLevel world = Minecraft.getInstance().level;
        if (world == null) return null;

        switch (s) {
            case JET_BOOTS -> {
                if (focus instanceof Player player) {
                    return new MovingSoundJetBoots(player);
                }
            }
            case MINIGUN -> {
                if (focus instanceof Player || focus instanceof DroneEntity) {
                    return new MovingSoundMinigun((Entity) focus);
                } else if (focus instanceof BlockPos pos) {
                    BlockEntity te = world.getBlockEntity(pos);
                    return te == null ? null : new MovingSoundMinigun(te);
                }
            }
            case ELEVATOR -> {
                if (focus instanceof BlockPos pos) {
                    BlockEntity te = world.getBlockEntity(pos);
                    return te instanceof ElevatorBaseBlockEntity ? new MovingSoundElevator((ElevatorBaseBlockEntity) te) : null;
                }
            }
            case AIR_LEAK -> {
                if (focus instanceof BlockPos pos) {
                    AbstractTickableSoundInstance sound = posToTickableSound.get(pos);
                    if (sound != null && !sound.isStopped()) {
                        return null;  // a sound is still playing; don't start another one
                    }
                    BlockEntity te = world.getBlockEntity(pos);
                    if (te != null && PNCCapabilities.getAirHandler(te).isPresent()) {
                        sound = new MovingSoundAirLeak(te, (Direction) extraData[0]);
                        posToTickableSound.put(pos, sound);
                        return sound;
                    }
                }
                // can get here if the TE is not valid (e.g. chunk not fully loaded)
                return null;
            }
            case JACKHAMMER -> {
                if (focus instanceof Player player) {
                    return MovingSoundJackhammer.startOrContinue(player);
                }
            }
        }
        throw new IllegalArgumentException("Invalid moving sound " + s + " for focus object " + focus);
    }

public static void playMovingSound(Sound s, Object focus, Object... extraData) {
        AbstractTickableSoundInstance movingSound = createMovingSound(s, focus, extraData);
        if (movingSound != null) {
            Minecraft.getInstance().getSoundManager().play(movingSound);
        }
    }

@Override
    public void tick() {
        if (!player.isAlive()) {
            return;
        }

        JetBootsStateTracker.JetBootsState jbState = JetBootsStateTracker.getClientTracker().getJetBootsState(player);

        if (endTimer == Integer.MAX_VALUE &&
                (!jbState.isEnabled() || (!jbState.isActive() && (player.onGround() || player.isFallFlying())))) {
            endTimer = END_TICKS;
        }
        if (endTimer <= END_TICKS) {
            if (player.onGround() || !jbState.isActive()) {
                endTimer--;
            } else {
                endTimer = Integer.MAX_VALUE;
            }
        }

        x = (float) player.getX();
        y = (float) player.getY();
        z = (float) player.getZ();

        if (endTimer > 0 && endTimer <= END_TICKS) {
            targetPitch = 0.5F;
            volume = volumeFromConfig(jbState.isBuilderMode()) - ((END_TICKS - endTimer) / 50F);
        } else {
            if (jbState.isActive()) {
                double vel = player.getDeltaMovement().length();
                targetPitch = 0.9F + (float) vel / 15;
                volume = volumeFromConfig(jbState.isBuilderMode()) + (float) vel / 15;
            } else {
                targetPitch = 0.9F;
                volume = volumeFromConfig(jbState.isBuilderMode()) * 0.8F;
            }
            handleParticles(jbState.isActive(), jbState.isBuilderMode());
        }
        pitch += (targetPitch - pitch) / 10F;
        if (player.isInWater()) {
            pitch *= 0.75f;
            volume *= 0.5f;
        }
    }
